import{_ as o,C as r,o as s,c as n,ak as a,E as i}from"./chunks/framework.BqbqgNoY.js";const f=JSON.parse(`{"title":"What's new in v6?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/whats-new.md","filePath":"guide/whats-new.md","lastUpdated":1795863147000}`),l={name:"guide/whats-new.md"};function d(h,e,c,p,u,g){const t=r("DiceRoller");return s(),n("div",null,[e[0]||(e[0]=a('<h1 id="what-s-new-in-v6" tabindex="-1">What&#39;s new in v6? <a class="header-anchor" href="#what-s-new-in-v6" aria-label="Permalink to &quot;What&#39;s new in v6?&quot;">​</a></h1><p>Version 6 is a substantial rewrite of RPG Dice Roller. It&#39;s written in TypeScript, with a new expression-based architecture that makes it easier to build complex rolls, inspect results and customise the library to suit your application.</p><p>Many familiar dice notations still work as before, but there are breaking changes to the JavaScript API and some notation and evaluation behaviour.</p><div class="warning custom-block"><p class="custom-block-title">Upgrading from v5?</p><p>Version 6 is not a drop-in replacement for v5. In particular, saved rolls and histories exported by v5 cannot be imported directly into v6. See <a href="./migration.html">Migrating from v5 to v6</a> for practical upgrade instructions.</p></div><h2 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h2><h3 id="rolling-dice-and-working-with-results" tabindex="-1">Rolling dice and working with results <a class="header-anchor" href="#rolling-dice-and-working-with-results" aria-label="Permalink to &quot;Rolling dice and working with results&quot;">​</a></h3><ul><li><code>DiceRoll</code> and <code>DiceRoller</code> have been replaced by <code>Roll</code> and <code>Roller</code>. The new <code>roll()</code> function provides a shorthand for standalone rolls.</li><li>Re-rolling with <code>Roll.reroll()</code> returns a new roll rather than changing the existing result.</li><li>Roll history is now managed through <code>Roller.history</code>, a <code>RollHistory</code> instance.</li><li>The old result classes have been replaced by an evaluated result tree, accessible through <code>roll.result</code>. Modifier flags are semantic names rather than formatted symbols.</li><li>Output formatting is handled by presenters. Use <code>present()</code> instead of the old <code>output</code> property.</li></ul><p>See <a href="./usage/">Rolling dice</a>, <a href="./usage/working-with-results.html">Working with results</a> and <a href="./usage/roll-history.html">Roll history</a>.</p><h3 id="importing-and-exporting" tabindex="-1">Importing and exporting <a class="header-anchor" href="#importing-and-exporting" aria-label="Permalink to &quot;Importing and exporting&quot;">​</a></h3><p>The import and export data structure has changed to support the expression and result trees. Version 5 exports are not directly compatible with v6. Use the <a href="./packages/converter.html">data converter</a> to migrate saved rolls and histories without rolling again.</p><p>Export formats are now specified using <code>&#39;object&#39;</code>, <code>&#39;json&#39;</code> or <code>&#39;base64&#39;</code>, and <code>export()</code> returns an object by default rather than a JSON string.</p><p>See <a href="./usage/importing-and-exporting.html">Importing and exporting</a>.</p><h3 id="configuration-and-customisation" tabindex="-1">Configuration and customisation <a class="header-anchor" href="#configuration-and-customisation" aria-label="Permalink to &quot;Configuration and customisation&quot;">​</a></h3><ul><li>The random-number implementation now uses <a href="https://github.com/dubzzz/pure-rand" target="_blank" rel="noreferrer">pure-rand</a> instead of random-js. The engine API and available built-in engines have changed. Seeded sequences are not guaranteed to match those from v5.</li><li>Dice definitions, modifier handlers and random engines use registries. Configuration can be shared across rolls or isolated from other parts of your application, rather than relying on global settings.</li><li>Error classes are exposed through the <code>errors</code> namespace, with new validation, notation, evaluation and import errors.</li><li>The bundle paths have changed from <code>lib/</code> to <code>dist/</code>. Check any imports that refer directly to a bundle file rather than the package name.</li></ul><p>See <a href="./usage/roll-options.html">Configuring rolls</a>, <a href="./customisation/">Customisation</a>, <a href="./usage/handling-errors.html">Handling errors</a> and <a href="./getting-started.html">Get started</a>.</p><h3 id="notation-and-output-changes" tabindex="-1">Notation and output changes <a class="header-anchor" href="#notation-and-output-changes" aria-label="Permalink to &quot;Notation and output changes&quot;">​</a></h3><ul><li>Fractional computed dice quantities are rejected instead of truncated. For example, <code>(3/2)d6</code> is invalid; use an explicit rounding function if you intend to roll an integer quantity.</li><li>Target success and failure conditions must be written together, and the last matching condition determines the score.</li><li>Critical success and failure markers in the default text output have changed from <code>**</code> and <code>__</code> to <code>cs</code> and <code>cf</code>. Target success and failure markers can now repeat to indicate a weighted score.</li></ul><h2 id="new-features" tabindex="-1">New features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New features&quot;">​</a></h2><h3 id="more-expressive-notation" tabindex="-1">More expressive notation <a class="header-anchor" href="#more-expressive-notation" aria-label="Permalink to &quot;More expressive notation&quot;">​</a></h3><p>Expressions can be used to calculate the quantity of dice, the number of sides and the number of results to keep or drop. These calculations can include other dice rolls, functions and roll groups.</p><p>Comparisons and ternary conditionals allow notation to make decisions based on evaluated values, while variables allow you to supply data from your application without constructing new notation strings.</p><table tabindex="0"><thead><tr><th>Example</th><th>What it does</th></tr></thead><tbody><tr><td><code>(d4)d6</code></td><td>Roll a d4 to determine how many d6s to roll.</td></tr><tr><td><code>d(2d4)</code></td><td>Roll two d4s to determine the number of sides of another die.</td></tr><tr><td><code>4d6kh(d4)</code></td><td>Keep a number of the highest results determined by a d4.</td></tr><tr><td><code>(max(4,2))d10</code></td><td>Use the larger of two values as the dice quantity.</td></tr><tr><td><code>(d20+5&gt;=15)</code></td><td>Evaluate a comparison to 1 or 0.</td></tr><tr><td><code>((d20)&gt;=15)?(2d6):(0)</code></td><td>Conditionally roll damage based on an expression comparison.</td></tr><tr><td><code>d20+$character.attackBonus</code></td><td>Add a value supplied by your application.</td></tr></tbody></table>',22)),i(t,{notation:"(d4)d6",data:{bonus:3,character:{attackBonus:2,isPoisoned:!0}}}),e[1]||(e[1]=a('<p>Try these expressions and experiment with your own combinations in the <a href="https://tools.dice-roller.dev/playground" target="_blank" rel="noreferrer">dice playground</a>.</p><p>See <a href="./notation/maths.html">Maths</a>, <a href="./notation/comparisons-and-ternaries.html">Comparisons and ternaries</a> and <a href="./notation/variables.html">Variables</a>.</p><h3 id="custom-dice" tabindex="-1">Custom dice <a class="header-anchor" href="#custom-dice" aria-label="Permalink to &quot;Custom dice&quot;">​</a></h3><p>You can define dice with arbitrary numeric faces, including repeated faces to give some values a greater probability of being rolled. Ranges support custom minimums, maximums and step sizes.</p><table tabindex="0"><thead><tr><th>Example</th><th>What it does</th></tr></thead><tbody><tr><td><code>d{1,1,2,5}</code></td><td>Roll a die with four faces, two of which are 1.</td></tr><tr><td><code>d{-3...3}</code></td><td>Roll a value from -3 to 3.</td></tr><tr><td><code>d{0:0.5:2}</code></td><td>Roll one of 0, 0.5, 1, 1.5 or 2.</td></tr></tbody></table>',5)),i(t,{notation:"4d{1,1,2,5}",data:{bonus:3,character:{attackBonus:2,isPoisoned:!0}}}),e[2]||(e[2]=a('<p>For more specialised game mechanics, you can also register your own die factories and provide custom rolling behaviour.</p><p>See <a href="./notation/dice.html">Dice notation</a> and <a href="./customisation/dice.html">Custom dice</a>.</p><h3 id="new-modifier-capabilities" tabindex="-1">New modifier capabilities <a class="header-anchor" href="#new-modifier-capabilities" aria-label="Permalink to &quot;New modifier capabilities&quot;">​</a></h3><ul><li><strong>Weighted targets:</strong> count some successes or failures more heavily than others. For example, <code>4d10&gt;=8&gt;=10:2f=1:2</code> counts a roll of 10 as two successes and a roll of 1 as two failures.</li><li><strong>Repeating modifier limits:</strong> limit explosions, re-rolls or unique retries, for example <code>d6!3</code>.</li><li><strong>Multiple dice per trigger:</strong> generate several dice on an explosion or re-roll, for example <code>d6!2:3</code> or <code>d6ro:3</code>.</li><li><strong>Matching-batch explosions:</strong> use <code>2d6!m</code> to roll another batch whenever all the dice in a batch match.</li><li><strong>Calculated keep/drop counts:</strong> use an expression instead of a fixed number when choosing how many results to keep or drop.</li></ul>',4)),i(t,{notation:"4d10>=8>=10:2f=1:2",data:{bonus:3,character:{attackBonus:2,isPoisoned:!0}}}),e[3]||(e[3]=a(`<p>See <a href="./notation/modifiers.html">Modifiers</a>. You can also configure modifier execution order and replace built-in modifier behaviour using the <a href="./customisation/modifiers.html">modifier registry</a>.</p><h3 id="parsing-and-building-expressions" tabindex="-1">Parsing and building expressions <a class="header-anchor" href="#parsing-and-building-expressions" aria-label="Permalink to &quot;Parsing and building expressions&quot;">​</a></h3><p>The new abstract syntax tree (AST) separates parsing from evaluation. Parse notation without rolling dice, inspect the resulting expression, or construct rolls programmatically using the AST builders.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { Roll, ast } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@dice-roller/rpg-dice-roller&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> expression</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ast.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">binary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;+&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ast.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> roll</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Roll</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(expression);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(roll.total);</span></span></code></pre></div><p>This is particularly useful for graphical notation builders, reusable game mechanics and custom dice that cannot be expressed using the built-in notation syntax.</p><p>See <a href="./usage/parsing-and-building-expressions.html">Parsing and building expressions</a>.</p><h3 id="richer-roll-results" tabindex="-1">Richer roll results <a class="header-anchor" href="#richer-roll-results" aria-label="Permalink to &quot;Richer roll results&quot;">​</a></h3><p>The evaluated result tree follows the structure of the original expression. Each pool includes information about the resolved die, the original and modified values of its results, and how each result contributes to the total.</p><p>This makes it easier to build interfaces that distinguish die types, display modifier effects or inspect calculations within complex expressions.</p><p>See <a href="./usage/working-with-results.html">Working with results</a>.</p><h3 id="presenters" tabindex="-1">Presenters <a class="header-anchor" href="#presenters" aria-label="Permalink to &quot;Presenters&quot;">​</a></h3><p>Result formatting is now separate from rolling. The built-in text presenter supports configurable modifier symbols and other formatting options, and you can implement your own presenter for any output format.</p><p>First-party SVG and terminal presenters are also available for displaying results graphically or in a terminal.</p><p>See <a href="./customisation/presenters.html">Presenters</a>.</p><h3 id="random-engines-and-external-dice-sources" tabindex="-1">Random engines and external dice sources <a class="header-anchor" href="#random-engines-and-external-dice-sources" aria-label="Permalink to &quot;Random engines and external dice sources&quot;">​</a></h3><p>Choose a random engine by name, supply a seed or register your own engine. You can configure engines for a roller or override them for individual rolls.</p><p>The new <code>drawDie</code> option also lets an external source supply individual die values as they&#39;re needed, while the library continues to apply modifiers and calculate totals.</p><p>This allows integrations with 3D dice rollers, remote dice services or prompts for physical dice results. External sources can be synchronous or asynchronous; ordinary rolls remain synchronous.</p><p>See <a href="./customisation/random-number-generator.html">Random number generator</a> and <a href="./customisation/external-dice.html">External dice sources</a>.</p><h3 id="restoring-finished-results" tabindex="-1">Restoring finished results <a class="header-anchor" href="#restoring-finished-results" aria-label="Permalink to &quot;Restoring finished results&quot;">​</a></h3><p>In addition to importing complete, versioned roll snapshots, v6 supports concise imports that specify notation and finished dice results. The library reconstructs the result tree and calculates totals without rolling again.</p><p>For concise imports, modifier effects must already be included in the supplied results. Use an external dice source instead if you want the library to apply modifiers to supplied die draws.</p><p>See <a href="./usage/importing-and-exporting.html">Importing and exporting</a>.</p><h2 id="fixes-and-behaviour-changes" tabindex="-1">Fixes and behaviour changes <a class="header-anchor" href="#fixes-and-behaviour-changes" aria-label="Permalink to &quot;Fixes and behaviour changes&quot;">​</a></h2><h3 id="more-useful-errors" tabindex="-1">More useful errors <a class="header-anchor" href="#more-useful-errors" aria-label="Permalink to &quot;More useful errors&quot;">​</a></h3><p>Invalid notation produces clearer diagnostics, including source locations for syntax errors. <code>NotationError.format()</code> can display the offending source line with a caret pointing to the problem.</p><p>For example, invalid quantities such as <code>0d6</code> now produce a more useful error. Computed quantities that evaluate to zero are supported, allowing expressions to determine whether a pool rolls any dice.</p><p>See <a href="./usage/handling-errors.html">Handling errors</a>.</p><h3 id="improved-average-calculations" tabindex="-1">Improved average calculations <a class="header-anchor" href="#improved-average-calculations" aria-label="Permalink to &quot;Improved average calculations&quot;">​</a></h3><p>Unmodified pools use the resolved die average rather than the midpoint of its minimum and maximum. This matters for dice with non-uniform face values: <code>3d{1,1,6}</code> has an average total of 8, not 10.5.</p><p>The library still uses the midpoint fallback for modified rolls and conditionals. This change does not make <code>averageTotal</code> a general probability calculation, and the result may not be the true statistical mean.</p><p>See <a href="./usage/working-with-results.html#calculated-totals">Calculated totals</a>.</p><h3 id="limits-on-additional-rolls" tabindex="-1">Limits on additional rolls <a class="header-anchor" href="#limits-on-additional-rolls" aria-label="Permalink to &quot;Limits on additional rolls&quot;">​</a></h3><p>Repeating modifiers share a configurable per-pool budget for additional dice draws, as well as their iteration limits. When the budget is exhausted, they stop generating new dice and retain the results reached so far.</p><p>This helps control potentially large branching explosions and re-rolls, without imposing a single budget on the whole expression.</p><p>See <a href="./usage/roll-options.html#roll-limits">Roll limits</a>.</p><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="./migration.html">Migrating from v5 to v6</a> — update an existing application.</li><li><a href="./getting-started.html">Get started</a> — install and load v6.</li><li><a href="./usage/">Usage</a> — learn the new API.</li><li><a href="./notation/">Notation</a> — explore dice types, modifiers and expressions.</li><li><a href="./customisation/">Customisation</a> — adapt the library to your application.</li><li><a href="https://github.com/dice-roller/rpg-dice-roller/discussions/304" target="_blank" rel="noreferrer">v6 release discussion</a> — development discussion and release tracking.</li></ul>`,38))])}const b=o(l,[["render",d]]);export{f as __pageData,b as default};
